examples.code:
DROP TABLE IF EXISTS scores;
CREATE TABLE scores (student TEXT, score INTEGER);
INSERT INTO scores VALUES ('Asha',88),('Bilal',72);
-- Show learners who scored at least 80
SELECT student,score FROM scores WHERE score>=80 ORDER BY student;

DROP TABLE IF EXISTS products;
CREATE TABLE products (product_name TEXT, price INTEGER);
INSERT INTO products VALUES ('Keyboard',1200),('Mouse',600);
SELECT product_name, price -- amount stored in whole currency units
FROM products ORDER BY product_name;

DROP TABLE IF EXISTS orders;
CREATE TABLE orders (order_id INTEGER PRIMARY KEY, amount INTEGER);
INSERT INTO orders VALUES (1,250),(2,900);
/* Report only high-value orders.
   This comment spans two lines. */
SELECT order_id,amount FROM orders WHERE amount>=500 ORDER BY order_id;

DROP TABLE IF EXISTS invoices;
CREATE TABLE invoices (invoice_id INTEGER PRIMARY KEY, subtotal INTEGER);
INSERT INTO invoices VALUES (1,1000),(2,500);
SELECT invoice_id,subtotal,subtotal*0.18 AS tax_amount -- illustrative 18 percent tax calculation
FROM invoices ORDER BY invoice_id;

DROP TABLE IF EXISTS flags;
CREATE TABLE flags (flag_id INTEGER PRIMARY KEY, enabled INTEGER);
INSERT INTO flags VALUES (1,1),(2,0);
-- SELECT * FROM flags WHERE enabled=0;
SELECT flag_id FROM flags WHERE enabled=1 ORDER BY flag_id;

